def n(s, o):
    return o * 12 + s + 1

def cell(pattern, row, ch, note_val=None, inst=None, vol=None, fx=None, fxp=None):
    args = {"pattern": pattern, "row": row, "channel": ch}
    if note_val is not None: args["note"] = note_val
