# Chord data
arp_Am = [n(9,4), n(0,5), n(4,5), n(9,5)]
arp_F  = [n(5,4), n(9,4), n(0,5), n(5,5)]
arp_C  = [n(0,4), n(4,4), n(7,4), n(0,5)]
arp_G  = [n(7,3), n(11,3), n(2,4), n(7,4)]
chord_arps = [arp_Am, arp_F, arp_C, arp_G]
bass_notes = [n(9,2), n(5,2), n(0,3), n(7,2)]

L_A3=n(9,3); L_C4=n(0,4); L_D4=n(2,4); L_E4=n(4,4); L_F4=n(5,4)
L_G3=n(7,3); L_G4=n(7,4); L_A4=n(9,4); L_B3=n(11,3)
L_C5=n(0,5); L_D5=n(2,5); L_E5=n(4,5)

mel_a = [[L_A4,L_C5,L_E5,L_A4,L_G4,L_E4,L_D4,L_C4],[L_F4,L_A4,L_C5,L_F4,L_E4,L_D4,L_C4,L_A3],
         [L_C4,L_E4,L_G4,L_A4,L_G4,L_E4,L_C4,L_E4],[L_B3,L_D4,L_G4,L_G4,L_F4,L_E4,L_D4,L_G3]]
mel_b = [[L_E5,L_D5,L_C5,L_A4,L_G4,L_A4,L_C5,L_E5],[L_A4,L_C5,L_F4,L_A4,L_C5,L_A4,L_G4,L_F4],
         [L_E4,L_G4,L_C5,L_E4,L_D4,L_C4,L_E4,L_G4],[L_D4,L_G4,L_B3,L_D4,L_E4,L_D4,L_B3,L_G3]]
mel_c = [[L_A4,L_C5,L_E5,L_C5,L_A4,L_E5,L_C5,L_A4],[L_F4,L_A4,L_C5,L_A4,L_F4,L_C5,L_A4,L_F4],
         [L_C4,L_E4,L_G4,L_E4,L_C4,L_G4,L_E4,L_C4],[L_G3,L_B3,L_D4,L_B3,L_G3,L_D4,L_B3,L_G3]]
mel_br = [[L_A4,0,L_C5,0,L_E5,0,L_A4,0],[L_F4,0,L_A4,0,L_C5,0,L_F4,0],
