pad_notes = [n(9,4), n(5,4), n(0,4), n(7,3)]

VK=55; VS=48; VH=35; VB=55; VL=52; VA=40; VP=35; VC=45

# Pattern 0: Intro
for ci in range(4):
    br = ci * 8
    for i in range(8):
        r = br + i
        if i % 4 == 0: cell(0, r, 0, None, 1, VK)
        if i % 4 == 2: cell(0, r, 1, None, 2, VS)
        if i % 2 == 0: cell(0, r, 2, None, 3, VH)
        if i == 0: cell(0, r, 3, bass_notes[ci], 4, VB)
        if i % 2 == 0: cell(0, r, 5, chord_arps[ci][i%4], 6, VA)

# Pattern 1: Main A
for ci in range(4):
    br = ci * 8
    for i in range(8):
        r = br + i
        if i in [0,4]: cell(1, r, 0, None, 1, VK)
        if i == 6 and ci%2==0: cell(1, r, 0, None, 1, VK-10)
        if i in [2,6]: cell(1, r, 1, None, 2, VS)
        cell(1, r, 2, None, 3, VH if i%2==0 else VH-10)
        if i == 0: cell(1, r, 3, bass_notes[ci], 4, VB)
        if i == 4: cell(1, r, 3, bass_notes[ci]+12, 4, VB-5)
        if i % 2 == 0: cell(1, r, 4, mel_a[ci][i], 5, VL)
        cell(1, r, 5, chord_arps[ci][i%4], 6, VA-5)

# Pattern 2: Main B
for ci in range(4):
    br = ci * 8
    for i in range(8):
        r = br + i
        if i in [0,4]: cell(2, r, 0, None, 1, VK)
        if i == 3: cell(2, r, 0, None, 1, VK-12)
        if i in [2,6]: cell(2, r, 1, None, 2, VS)
        if i == 5: cell(2, r, 1, None, 8, VC)
        cell(2, r, 2, None, 3, VH if i%2==0 else VH-8)
        if i == 0: cell(2, r, 3, bass_notes[ci], 4, VB)
        if i == 4: cell(2, r, 3, bass_notes[ci]+12, 4, VB-5)
        if i % 2 == 0: cell(2, r, 4, mel_b[ci][i], 5, VL)
        if i % 2 == 0: cell(2, r, 5, chord_arps[ci][i%4], 6, VA)

# Pattern 3: Bridge
for ci in range(4):
    br = ci * 8
    for i in range(8):
        r = br + i
        if i == 0: cell(3, r, 7, pad_notes[ci], 7, VP)
        if i % 2 == 0: cell(3, r, 5, chord_arps[ci][i%4], 6, VA-15)
        if mel_br[ci][i] > 0: cell(3, r, 4, mel_br[ci][i], 5, VL-10)
        if i == 0: cell(3, r, 3, bass_notes[ci], 4, VB-20)

# Pattern 4: Climax
for ci in range(4):
    br = ci * 8
    for i in range(8):
        r = br + i
        if i % 2 == 0: cell(4, r, 0, None, 1, VK)
        if i % 2 == 1: cell(4, r, 2, None, 3, VH)
        if i % 4 == 2: cell(4, r, 1, None, 2, VS)
        if i in [0,4]: cell(4, r, 1, None, 2, VS+5)
        if i % 4 == 0: cell(4, r, 3, bass_notes[ci], 4, VB)
        if i % 4 == 2: cell(4, r, 3, bass_notes[ci]+12, 4, VB-3)
        cell(4, r, 4, mel_c[ci][i], 5, VL+5)
        cell(4, r, 5, chord_arps[ci][i%4], 6, VA)

# Pattern 5: Outro (same as intro for clean loop)
for ci in range(4):
    br = ci * 8
    for i in range(8):
        r = br + i
        if i % 4 == 0: cell(5, r, 0, None, 1, VK)
        if i % 4 == 2: cell(5, r, 1, None, 2, VS)
        if i % 2 == 0: cell(5, r, 2, None, 3, VH)
        if i == 0: cell(5, r, 3, bass_notes[ci], 4, VB)
        if i % 2 == 0: cell(5, r, 5, chord_arps[ci][i%4], 6, VA)

# 6. Set order - MUST be after all pattern data
order = [0, 1, 2, 1, 3, 4, 1, 2, 5]
for i, pat in enumerate(order):
    add("order_set", {"position": i, "pattern": pat})

# 7. Set song metadata - MUST be last
add("song_set", {"bpm": 140, "speed": 3, "length": 9, "loop_start": 0})

# Save
with open('/workspace/final_batch.json', 'w') as f:
    json.dump(commands, f)

print(f"Final batch: {len(commands)} commands")
