import subprocess, json, os

# Try rendering with explicit start and stop positions
for stop in [1, 2, 3, 5, 8, 10, 20, 31]:
    result = subprocess.run(
        ['ft2', 'call', 'module_render', 
         json.dumps({
             "path": f"test_stop{stop}.wav",
             "rate": 44100, "bits": 16, "amp": 8,
             "start": 0, "stop": stop
         })],
        capture_output=True, text=True
    )
    # Parse the duration from output
    out = result.stdout.strip()
    try:
        import re
        m = re.search(r'"duration_seconds":([\d.]+)', out)
        if m:
            dur = float(m.group(1))
            print(f"stop={stop:2d}: {dur:.2f}s")
        else:
            print(f"stop={stop:2d}: {out[:100]}")
    except:
        print(f"stop={stop:2d}: {out[:100]}")
PYEOF
"}

